<?php
namespace App\Http\Controllers; use App\Models\Complaint; use Illuminate\Http\Request; class ComplaintController extends Controller { public function index(){return Complaint::with('facility')->get();} public function store(Request $r){$data=$r->validate(['facility_id'=>'required|exists:facilities,id','description'=>'required|string','status'=>'required|in:Open,In Progress,Resolved']);return response()->json(Complaint::create($data),201);} public function show(Complaint $complaint){return $complaint->load('facility');} public function update(Request $r,Complaint $complaint){$data=$r->validate(['facility_id'=>'required|exists:facilities,id','description'=>'required|string','status'=>'required|in:Open,In Progress,Resolved']);$complaint->update($data);return $complaint;} public function destroy(Complaint $complaint){$complaint->delete();return response()->noContent();} }
